n its direct stdout/status.\nCompare current command observations and the actual test bodies with the original\nsource. A historical pass, a count without execution, or an author's claim does\nnot establish this result.\n\n=== test/component/hello-cli.test.mjs\nimport { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { spawnSync } from 'node:child_process';\n\ntest('CLI process satisfies its output contract', () => {\n  const result = spawnSync(process.execPath, ['generated/hello-world.mjs'], { encoding: 'utf8' });\n  assert.equal(result.status, 0);\n  assert.equal(result.stdout, 'Hello, world!\\n');\n});\n\n=== test/uat/hello-cli.uat.test.mjs\nimport { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { spawnSync } from 'node:child_process';\n\ntest('a user receives the exact promised greeting', () => {\n  const result = spawnSync(process.execPath, ['generated/hello-world.mjs'], { encoding: 'utf8' });\n  assert.equal(result.status, 0);\n  assert.equal(result.stdout, 'Hello, world!\\n');\n});\n\n=== test-execution-plan.json\n{\n  \"command\": \"node\",\n  \"args\": [\n    \"--test\",\n    \"test/component/hello-cli.test.mjs\",\n    \"test/uat/hello-cli.uat.test.mjs\"\n  ],\n  \"expectedTestPassCount\": 2,\n  \"expectedStdoutMatch\": \"fail 0\",\n  \"assertedReturnValue\": \"Hello, world!\",\n  \"cwd\": \".\",\n  \"env\": {}\n}\n\n=== digests\nfe8f40803a256b5b65c97f5f4cae862fd55b37cb81f2a803c56c3f654c22e9ef  generated/hello-world.mjs\n028073e4cb24bd7444dd15d48b0e16d37df236edf7a003cb3ca26286aca6c585  source/basic-cli.oracle.json\nb96765496fe0c3888365ba72780af33824fa7f34acdb042af45df4d120ba0145  design/implementation-design.md\n617dd54841f7128842616ce42a3befb15b30cd454215894c067980e5ede43406  design/test-design.md\nce602ce2cc0fcefaba288623a675a770d11bc14d224b90045aebbe031330172f  source/original-basic-cli.txt\n29e669318aa0c9dc2fceca23f8caf22b01e475cd3f918070f980c70ac00355b3  source/witness-contract.md\n9aaa62cadeaa745